        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <li class="text-center flex-fill @(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                @if (isCompleted)
                {
                    <button class="btn btn-link text-success p-0 text-decoration-none" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
