                    <span>
                        <span class="badge rounded-pill @(isCurrent ? "bg-primary" : "bg-secondary")">@(stepIndex + 1)</span>
                        @StepNames[stepIndex]
                    </span>
                }
            </li>
        }
    </ol>
</nav>

